def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

def special_factorial(n):
    result = 1
    for i in range(1, n+1):
        result *= factorial(i)
    return result

# Test the function with sample input
print(special_factorial(4))  # Output should be 288

